<section class="card narrow"><p class="eyebrow"><?= $e($ticket['client_name']) ?></p><h1><?= $e($title) ?></h1><?php if($error): ?><p class="error" role="alert"><?= $e($error) ?></p><?php endif ?><div class="tabs"><?php if($wechatEnabled): ?><button type="button" data-tab="qr">微信扫码</button><?php endif ?><?php if($ticket['intent']==='LOGIN'): ?><button type="button" data-tab="password">账号密码</button><?php endif ?></div>
<?php if($wechatEnabled): ?><div id="qr" data-panel data-active="<?= $tab==='qr'?'1':'0' ?>"><div class="qr" data-qr data-ticket="<?= $e($ticket['id']) ?>" data-key="<?= $e($qrKey) ?>" data-expires="<?= $e($ticket['expires_at']) ?>"><img width="240" height="240" alt="微信小程序登录码" hidden><p data-qr-message>正在获取小程序码…</p></div><p class="muted center">微信扫一扫，在小程序中确认<?= $ticket['intent']==='LINK'?'绑定':'登录' ?></p><p class="center" data-countdown></p><form method="post" action="/login/refresh"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="request" value="<?= $e($ticket['id']) ?>"><button class="secondary" type="submit">刷新登录码</button></form><form id="qr-finish" method="post" action="/login/finish"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="request" value="<?= $e($ticket['id']) ?>"></form></div><?php endif ?>
<?php if($ticket['intent']==='LOGIN'): ?><form id="password" data-panel data-active="<?= !$wechatEnabled||$tab==='password'?'1':'0' ?>" method="post" action="/login/password"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="request" value="<?= $e($ticket['id']) ?>"><label>邮箱或账号<input name="username" autocomplete="username" required maxlength="191"></label><label>密码<input name="password" type="password" autocomplete="current-password" required maxlength="72"></label><button type="submit">登录并继续</button><div class="actions"><a href="/register">注册账号</a><a href="/forgot-password">忘记密码</a></div></form><?php endif ?>
<form class="spaced" method="post" action="/login/cancel"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="request" value="<?= $e($ticket['id']) ?>"><button class="text" type="submit">取消本次请求</button></form></section>